0\u0001 \u0001d\u0001 – \u0002@m0\u0002 \u0002d\u0002\u001Emedium~y\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001 – \u0002y\u0002 \u0002@m0\u0002 \u0002d\u0002\u001Elong~d\u001F\u0001y\u0001 \u0001@m1\u0001 \u0001d\u0001–\u0002d\u0002\u001Elong~M\u001F\u0001y\u0001 \u0001@m1\u0001 \u0001d\u0001 – \u0002@m1\u0002 \u0002d\u0002\u001Elong~y\u001F\u0001y\u0001 \u0001@m1\u0001 \u0001d\u0001 – \u0002y\u0002 \u0002@m1\u0002 \u0002d\u0002\u001Eday~d\u001F\u0001@m0\u0001 \u0001d\u0001–\u0002d\u0002\u001Eday~y\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001 – \u0002y\u0002 \u0002@m0\u0002 \u0002d\u0002\u001Eii\u001Dshort\u001F\u0001y\u0001-\u0001MM\u0001-\u0001dd\u0001\u001Em0\u001Fꋍꆪ\u001Fꑍꆪ\u001Fꌕꆪ\u001Fꇖꆪ\u001Fꉬꆪ\u001Fꃘꆪ\u001Fꏃꆪ\u001Fꉆꆪ\u001Fꈬꆪ\u001Fꊰꆪ\u001Fꊯꊪꆪ\u001Fꊰꑋꆪ\u001Emedium\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001\u001Elong\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001\u001Ew0\u001Fꑬꆏꑍ\u001Fꆏꊂꋍ\u001Fꆏꊂꑍ\u001Fꆏꊂꌕ\u001Fꆏꊂꇖ\u001Fꆏꊂꉬ\u001Fꆏꊂꃘ\u001Efull\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001, \u0001@w0\u0001\u001Eday\u001F\u0001@m0\u0001 \u0001d\u0001ꑍ\u001EyMMM\u001F\u0001y\u0001 \u0001@m0\u0001\u001EyMMMM\u001F\u0001y\u0001 \u0001@m0\u0001\u001Ew1\u001Fꑬꆏ\u001Fꆏꋍ\u001Fꆏꑍ\u001Fꆏꌕ\u001Fꆏꇖ\u001Fꆏꉬ\u001Fꆏꃘ\u001Ew2\u001Fꆏ\u001Fꋍ\u001Fꑍ\u001Fꌕ\u001Fꇖ\u001Fꉬ\u001Fꃘ\u001Etime\u001F\u0001H\u0001:\u0001mm\u0001\u001Eshort~d\u001F\u0001y\u0001-\u0001MM\u0001-\u0001dd\u0001 – \u0001y\u0001-\u0001MM\u0001-\u0002dd\u0002\u001Eshort~M\u001F\u0001y\u0001-\u0001MM\u0001-\u0001dd\u0001 – \u0001y\u0001-\u0002MM\u0002-\u0002dd\u0002\u001Eshort~y\u001F\u0001y\u0001-\u0001MM\u0001-\u0001dd\u0001 – \u0002y\u0002-\u0002MM\u0002-\u0002dd\u0002\u001Emedium~d\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001ꑍ–\u0002d\u0002ꑍ\u001Emedium~M\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001ꑍ – \u0002@m0\u0002 \u0002d\u0002ꑍ\u001Emedium~y\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001ꑍ – \u0002y\u0002 \u0002@m0\u0002 \u0002d\u0002ꑍ\u001Elong~d\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001ꑍ–\u0002d\u0002ꑍ\u001Elong~M\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001ꑍ – \u0002@m0\u0002 \u0002d\u0002ꑍ\u001Elong~y\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001ꑍ – \u0002y\u0002 \u0002@m0\u0002 \u0002d\u0002ꑍ\u001Eday~d\u001F\u0001@m0\u0001 \u0001d\u0001ꑍ–\u0002d\u0002ꑍ\u001Eday~M\u001F\u0001@m0\u0001 \u0001d\u0001ꑍ – \u0002@m0\u0002 \u0002d\u0002ꑍ\u001Eday~y\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001ꑍ – \u0002y\u0002 \u0002@m0\u0002 \u0002d\u0002ꑍ\u001Eis\u001Dshort\u001F\u0001d\u0001.\u0001M\u0001.\u0001y\u0001\u001Em0\u001Fjan.\u001Ffeb.\u001Fmar.\u001Fapr.\u001Fmaí\u001Fjún.\u001Fjúl.\u001Fágú.\u001Fsep.\u001Fokt.\u001Fnóv.\u001Fdes.\u001Emedium\u001F\u0001d\u0001. \u0001@m0\u0001 \u0001y\u0001\u001Em1\u001Fjanúar\u001Ffebrúar\u001Fmars\u001Fapríl\u001Fmaí\u001Fjúní\u001Fjúlí\u001Fágúst\u001Fseptember\u001Foktóber\u001Fnóvember\u001Fdesember\u001Elong\u001F\u0001d\u0001. \u0001@m1\u0001 \u0001y\u0001\u001Ew0\u001Fsunnudagur\u001Fmánudagur\u001Fþriðjudagur\u001Fmiðvikudagur\u001Ffimmtudagur\u001Fföstudagur\u001Flaugardagur\u001Efull\u001F\u0001@w0\u0001, \u0001d\u0001. \u0001@m1\u0001 \u0001y\u0001\u001Eday\u001F\u0001d\u0001. \u0001@m0\u0001\u001Ew1\u001Fsun.\u001Fmán.\u001Fþri.\u001Fmið.\u001Ffim.\u001Ffös.\u001Flau.\u001Ew2\u001FS\u001FM\u001FÞ\u001FM\u001FF\u001FF\u001FL\u001Etime\u001F\u0001H\u0001:\u0001mm\u0001\u001Eshort~d\u001F\u0001d\u0001.\u0001M\u0001.\u0001y\u0001 – \u0002d\u0002.\u0001M\u0001.\u0001y\u0001\u001Eshort~M\u001F\u0001d\u0001.\u0001M\u0001.\u0001y\u0001 – \u0002d\u0002.\u0002M\u0002.\u0001y\u0001\u001Eshort~y\u001F\u0001d\u0001.\u0001M\u0001.\u0001y\u0001 – \u0002d\u0002.\u0002M\u0002.\u0002y\u0002\u001Emedium~d\u001F\u0001d\u0001.–\u0002d\u0002. \u0001@m0\u0001 \u0001y\u0001\u001Emedium~M\u001F\u0001d\u0001. \u0001@m0\u0001 – \u0002d\u0002. \u0002@m0\u0002 \u0001y\u0001\u001Emedium~y\u001F\u0001d\u0001. \u0001@m0\u0001 \u0001y\u0001 – \u0002d\u0002. \u0002@m0\u0002 \u0002y\u0002\u001Elong~d\u001F\u0001d\u0001.–\u0002d\u0002. \u0001@m1\u0001 \u0001y\u0001\u001Elong~M\u001F\u0001d\u0001. \u0001@m1\u0001 – \u0002d\u0002. \u0002@m1\u0002 \u0001y\u0001\u001Elong~y\u001F\u0001d\u0001. \u0001@m1\u0001 \u0001y\u0001 – \u0002d\u0002. \u0002@m1\u0002 \u0002y\u0002\u001Eday~d\u001F\u0001d\u0001.–\u0002d\u0002. \u0001@m0\u0001\u001Eday~M\u001F\u0001d\u0001. \u0001@m0\u0001 – \u0002d\u0002. \u0002@m0\u0002\u001Eday~y\u001F\u0001d\u0001. \u0001@m0\u0001 \u0001y\u0001 – \u0002d\u0002. \u0002@m0\u0002 \u0002y\u0002\u001Eit\u001Dshort\u001F\u0001dd\u0001/\u0001MM\u0001/\u0001yy\u0001\u001Em0\u001Fgen\u001Ffeb\u001Fmar\u001Fapr\u001Fmag\u001Fgiu\u001Flug\u001Fago\u001Fset\u001Fott\u001Fnov\u001Fdic\u001Emedium\u001F\u0001d\u0001 \u0001@m0\u0001 \u0001y\u0001\u001Em1\u001Fgennaio\u001Ffebbraio\u001Fmarzo\u001Faprile\u001Fmaggio\u001Fgiugno\u001Fluglio\u001Fagosto\u001Fsettembre\u001Fottobre\u001Fnovembre\u001Fdicembre\u001Elong\u001F\u0001d\u0001 \u0001@m1\u0001 \u0001y\u0001\u001Ew0\u001Fdomenica\u001Flunedì\u001Fmartedì\u001Fmercoledì\u001Fgiovedì\u001Fvenerdì\u001Fsabato\u001Efull\u001F\u0001@w0\u0001 \u0001d\u0001 \u0001@m1\u0001 \u0001y\u0001\u001Eday\u001F\u0001d\u0001 \u0001@m0\u0001\u001Ew1\u001Fdom\u001Flun\u001Fmar\u001Fmer\u001Fgio\u001Fven\u001Fsab\u001Ew2\u001FD\u001FL\u001FM\u001FM\u001FG\u001FV\u001FS\u001Etime\u001F\u0001H\u0001:\u0001mm\u0001\u001Eshort~d\u001F\u0001dd\u0001/\u0001MM\u0001/\u0001yy\u0001 – \u0002dd\u0002/\u0001MM\u0001/\u0001yy\u0001\u001Eshort~M\u001F\u0001dd\u0001/\u0001MM\u0001/\u0001yy\u0001 – \u0002dd\u0002/\u0002MM\u0002/\u0001yy\u0001\u001Eshort~y\u001F\u0001dd\u0001/\u0001MM\u0001/\u0001yy\u0001 – \u0002dd\u0002/\u0002MM\u0002/\u0002yy\u0002\u001Emedium~d\u001F\u0001dd\u0001–\u0002dd\u0002 \u0001@m0\u0001 \u0001y\u0001\u001Emedium~M\u001F\u0001dd\u0001 \u0001@m0\u0001 – \u0002dd\u0002 \u0002@m0\u0002 \u0001y\u0001\u001Emedium~y\u001F\u0001dd\u0001 \u0001@m0\u0001 \u0001y\u0001 – \u0002dd\u0002 \u0002@m0\u0002 \u0002y\u0002\u001Elong~d\u001F\u0001dd\u0001–\u0002dd\u0002 \u0001@m1\u0001 \u0001y\u0001\u001Elong~M\u001F\u0001dd\u0001 \u0001@m1\u0001 – \u0002dd\u0002 \u0002@m1\u0002 \u0001y\u0001\u001Elong~y\u001F\u0001dd\u0001 \u0001@m1\u0001 \u0001y\u0001 – \u0002dd\u0002 \u0002@m1\u0002 \u0002y\u0002\u001Eday~d\u001F\u0001dd\u0001–\u0002dd\u0002 \u0001@m0\u0001\u001Eday~M\u001F\u0001dd\u0001 \u0001@m0\u0001 – \u0002dd\u0002 \u0002@m0\u0002\u001Eday~y\u001F\u0001dd\u0001 \u0001@m0\u0001 \u0001y\u0001 – \u0002dd\u0002 \u0002@m0\u0002 \u0002y\u0002\u001Eit-CH\u001Dshort\u001F\u0001dd\u0001.\u0001MM\u0001.\u0001yy\u0001\u001Efull\u001F\u0001@w0\u0001, \u0001d\u0001 \u0001@m1\u0001 \u0001y\u0001\u001Eja\u001Dshort\u001F\u0001y\u0001/\u0001MM\u0001/\u0001dd\u0001\u001Emedium\u001F\u0001y\u0001/\u0001MM\u0001/\u0001dd\u0001\u001Elong\u001F\u0001y\u0001年\u0001M\u0001月\u0001d\u0001日\u001Ew0\u001F日曜日\u001F月曜日\u001F火曜日\u001F水曜日\u001F木曜日\u001F金曜日\u001F土曜日\u001Efull\u001F\u0001y\u0001年\u0001M\u0001月\u0001d\u0001日\u0001@w0\u0001\u001Eday\u001F\u0001M\u0001月\u0001d\u0001日\u001EyMMM\u001F\u0001y\u0001年\u0001M\u0001月\u001EyMMMM\u001F\u0001y\u0001年\u0001M\u0001月\u001EMMM\u001F\u0001M\u0001月\u001Ew1\u001F日\u001F月\u001F火\u001F水\u001F木\u001F金\u001F土\u001EEEEEE\u001F\u0001@w1\u0001\u001Etime\u001F\u0001H\u0001:\u0001mm\u0001\u001Eshort~d\u001F\u0001y\u0001/\u0001MM\u0001/\u0001dd\u0001～\u0001y\u0001/\u0001MM\u0001/\u0002dd\u0002\u001Eshort~M\u001F\u0001y\u0001/\u0001MM\u0001/\u0001dd\u0001～\u0001y\u0001/\u0002MM\u0002/\u0002dd\u0002\u001Eshort~y\u001F\u0001y\u0001/\u0001MM\u0001/\u0001dd\u0001～\u0002y\u0002/\u0002MM\u0002/\u0002dd\u0002\u001Emedium~d\u001F\u0001y\u0001/\u0001MM\u0001/\u0001dd\u0001～\u0001y\u0001/\u0001MM\u0001/\u0002dd\u0002\u001Emedium~M\u001F\u0001y\u0001/\u0001MM\u0001/\u0001dd\u0001～\u0001y\u0001/\u0002MM\u0002/\u0002dd\u0002\u001Emedium~y\u001F\u0001y\u0001/\u0001MM\u0001/\u0001dd\u0001～\u0002y\u0002/\u0002MM\u0002/\u0002dd\u0002\u001Elong~d\u001F\u0001y\u0001/\u0001MM\u0001/\u0001dd\u0001～\u0001y\u0001/\u0001MM\u0001/\u0002dd\u0002\u001Elong~M\u001F\u0001y\u0001/\u0001MM\u0001/\u0001dd\u0001～\u0001y\u0001/\u0002MM\u0002/\u0002dd\u0002\u001Elong~y\u001F\u0001y\u0001/\u0001MM\u0001/\u0001dd\u0001～\u0002y\u0002/\u0002MM\u0002/\u0002dd\u0002\u001Eday~d\u001F\u0001MM\u0001/\u0001dd\u0001～\u0001MM\u0001/\u0002dd\u0002\u001Eday~M\u001F\u0001MM\u0001/\u0001dd\u0001～\u0002MM\u0002/\u0002dd\u0002\u001Eday~y\u001F\u0001y\u0001/\u0001MM\u0001/\u0001dd\u0001～\u0002y\u0002/\u0002MM\u0002/\u0002dd\u0002\u001Ejgo\u001Dshort\u001F\u0001y\u0001-\u0001MM\u0001-\u0001dd\u0001\u001Em0\u001FNduŋmbi Saŋ\u001FPɛsaŋ Pɛ́pá\u001FPɛsaŋ Pɛ́tát\u001FPɛsaŋ Pɛ́nɛ́kwa\u001FPɛsaŋ Pataa\u001FPɛsaŋ Pɛ́nɛ́ntúkú\u001FPɛsaŋ Saambá\u001FPɛsaŋ Pɛ́nɛ́fɔm\u001FPɛsaŋ Pɛ́nɛ́pfúꞋú\u001FPɛsaŋ Nɛgɛ́m\u001FPɛsaŋ Ntsɔ̌pmɔ́\u001FPɛsaŋ Ntsɔ̌ppá\u001Emedium\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001\u001Elong\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001\u001Ew0\u001FSɔ́ndi\u001FMɔ́ndi\u001FÁpta Mɔ́ndi\u001FWɛ́nɛsɛdɛ\u001FTɔ́sɛdɛ\u001FFɛlâyɛdɛ\u001FSásidɛ\u001Efull\u001F\u0001@w0\u0001, \u0001y\u0001 \u0001@m0\u0001 \u0001dd\u0001\u001EyMMM\u001F\u0001y\u0001 \u0001@m0\u0001\u001EyMMMM\u001F\u0001y\u0001 \u0001@m0\u0001\u001EE\u001F\u0001@w0\u0001\u001Ew1\u001FSɔ́\u001FMɔ́\u001FÁM\u001FWɛ́\u001FTɔ́\u001FFɛ\u001FSá\u001EEEEEE\u001F\u0001@w1\u0001\u001Etime\u001F\u0001H\u0001:\u0001mm\u0001\u001Eshort~d\u001F\u0001y\u0001-\u0001MM\u0001-\u0001dd\u0001 – \u0001y\u0001-\u0001MM\u0001-\u0002dd\u0002\u001Eshort~M\u001F\u0001y\u0001-\u0001MM\u0001-\u0001dd\u0001 – \u0001y\u0001-\u0002MM\u0002-\u0002dd\u0002\u001Eshort~y\u001F\u0001y\u0001-\u0001MM\u0001-\u0001dd\u0001 – \u0002y\u0002-\u0002MM\u0002-\u0002dd\u0002\u001Emedium~d\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001–\u0002d\u0002\u001Emedium~M\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001 – \u0002@m0\u0002 \u0002d\u0002\u001Emedium~y\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001 – \u0002y\u0002 \u0002@m0\u0002 \u0002d\u0002\u001Elong~d\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001–\u0002d\u0002\u001Elong~M\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001 – \u0002@m0\u0002 \u0002d\u0002\u001Elong~y\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001 – \u0002y\u0002 \u0002@m0\u0002 \u0002d\u0002\u001Eday~d\u001F\u0001@m0\u0001 \u0001d\u0001–\u0002d\u0002\u001Eday~y\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001 – \u0002y\u0002 \u0002@m0\u0002 \u0002d\u0002\u001Ejmc\u001Dshort\u001F\u0001dd\u0001/\u0001MM\u0001/\u0001y\u0001\u001Em0\u001FJan\u001FFeb\u001FMac\u001FApr\u001FMei\u001FJun\u001FJul\u001FAgo\u001FSep\u001FOkt\u001FNov\u001FDes\u001Emedium\u001F\u0001d\u0001 \u0001@m0\u0001 \u0001y\u0001\u001Em1\u001FJanuari\u001FFebruari\u001FMachi\u001FAprilyi\u001FMei\u001FJunyi\u001FJulyai\u001FAgusti\u001FSeptemba\u001FOktoba\u001FNovemba\u001FDesemba\u001Elong\u001F\u0001d\u0001 \u0001@m1\u0001 \u0001y\u0001\u001Ew0\u001FJumapilyi\u001FJumatatuu\u001FJumanne\u001FJumatanu\u001FAlhamisi\u001FIjumaa\u001FJumamosi\u001Efull\u001F\u0001@w0\u0001, \u0001d\u0001 \u0001@m1\u0001 \u0001y\u0001\u001Ew1\u001FJpi\u001FJtt\u001FJnn\u001FJtn\u001FAlh\u001FIju\u001FJmo\u001Ew2\u001FJ\u001FJ\u001FJ\u001FJ\u001FA\u001FI\u001FJ\u001Etime\u001F\u0001H\u0001:\u0001mm\u0001\u001Eshort~d\u001F\u0001y\u0001-\u0001MM\u0001-\u0001dd\u0001 – \u0001y\u0001-\u0001MM\u0001-\u0002dd\u0002\u001Eshort~M\u001F\u0001y\u0001-\u0001MM\u0001-\u0001dd\u0001 – \u0001y\u0001-\u0002MM\u0002-\u0002dd\u0002\u001Eshort~y\u001F\u0001y\u0001-\u0001MM\u0001-\u0001dd\u0001 – \u0002y\u0002-\u0002MM\u0002-\u0002dd\u0002\u001Emedium~d\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001–\u0002d\u0002\u001Emedium~M\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001 – \u0002@m0\u0002 \u0002d\u0002\u001Emedium~y\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001 – \u0002y\u0002 \u0002@m0\u0002 \u0002d\u0002\u001Elong~d\u001F\u0001y\u0001 \u0001@m1\u0001 \u0001d\u0001–\u0002d\u0002\u001Elong~M\u001F\u0001y\u0001 \u0001@m1\u0001 \u0001d\u0001 – \u0002@m1\u0002 \u0002d\u0002\u001Elong~y\u001F\u0001y\u0001 \u0001@m1\u0001 \u0001d\u0001 – \u0002y\u0002 \u0002@m1\u0002 \u0002d\u0002\u001Eday~d\u001F\u0001@m0\u0001 \u0001d\u0001–\u0002d\u0002\u001Eday~y\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001 – \u0002y\u0002 \u0002@m0\u0002 \u0002d\u0002\u001Ejv\u001Dshort\u001F\u0001dd\u0001-\u0001MM\u0001-\u0001y\u0001\u001Em0\u001FJan\u001FFeb\u001FMar\u001FApr\u001FMei\u001FJun\u001FJul\u001FAgt\u001FSep\u001FOkt\u001FNov\u001FDes\u001Emedium\u001F\u0001d\u0001 \u0001@m0\u0001 \u0001y\u0001\u001Em1\u001FJanuari\u001FFebruari\u001FMaret\u001FApril\u001FMei\u001FJuni\u001FJuli\u001FAgustus\u001FSeptember\u001FOktober\u001FNovember\u001FDesember\u001Elong\u001F\u0001d\u0001 \u0001@m1\u0001 \u0001y\u0001\u001Ew0\u001FAhad\u001FSenin\u001FSelasa\u001FRabu\u001FKamis\u001FJumat\u001FSabtu\u001Efull\u001F\u0001@w0\u0001, \u0001d\u0001 \u0001@m1\u0001 \u0001y\u0001\u001Eday\u001F\u0001d\u0001 \u0001@m0\u0001\u001Ew1\u001FAhad\u001FSen\u001FSel\u001FRab\u001FKam\u001FJum\u001FSab\u001Ew2\u001FA\u001FS\u001FS\u001FR\u001FK\u001FJ\u001FS\u001Etime\u001F\u0001H\u0001:\u0001mm\u0001\u001Eshort~d\u001F\u0001dd\u0001-\u0001MM\u0001-\u0001y\u0001 – \u0002dd\u0002-\u0001MM\u0001-\u0001y\u0001\u001Eshort~M\u001F\u0001dd\u0001-\u0001MM\u0001-\u0001y\u0001 – \u0002dd\u0002-\u0002MM\u0002-\u0001y\u0001\u001Eshort~y\u001F\u0001dd\u0001-\u0001MM\u0001-\u0001y\u0001 – \u0002dd\u0002-\u0002MM\u0002-\u0002y\u0002\u001Emedium~d\u001F\u0001d\u0001 – \u0002d\u0002 \u0001@m0\u0001 \u0001y\u0001\u001Emedium~M\u001F\u0001d\u0001 \u0001@m0\u0001 – \u0002d\u0002 \u0002@m0\u0002 \u0001y\u0001\u001Emedium~y\u001F\u0001d\u0001 \u0001@m0\u0001 \u0001y\u0001 – \u0002d\u0002 \u0002@m0\u0002 \u0002y\u0002\u001Elong~d\u001F\u0001d\u0001 – \u0002d\u0002 \u0001@m1\u0001 \u0001y\u0001\u001Elong~M\u001F\u0001d\u0001 \u0001@m1\u0001 – \u0002d\u0002 \u0002@m1\u0002 \u0001y\u0001\u001Elong~y\u001F\u0001d\u0001 \u0001@m1\u0001 \u0001y\u0001 – \u0002d\u0002 \u0002@m1\u0002 \u0002y\u0002\u001Eday~d\u001F\u0001@m0\u0001 \u0001d\u0001–\u0002d\u0002\u001Eday~M\u001F\u0001d\u0001 \u0001@m0\u0001 – \u0002d\u0002 \u0002@m0\u0002\u001Eday~y\u001F\u0001d\u0001 \u0001@m0\u0001 \u0001y\u0001 – \u0002d\u0002 \u0002@m0\u0002 \u0002y\u0002\u001Eka\u001Dshort\u001F\u0001dd\u0001.\u0001MM\u0001.\u0001yy\u0001\u001Em0\u001Fიან\u001Fთებ\u001Fმარ\u001Fაპრ\u001Fმაი\u001Fივნ\u001Fივლ\u001Fაგვ\u001Fსექ\u001Fოქტ\u001Fნოე\u001Fდეკ\u001Emedium\u001F\u0001d\u0001 \u0001@m0\u0001. \u0001y\u0001\u001Em1\u001Fიანვარი\u001Fთებერვალი\u001Fმარტი\u001Fაპრილი\u001Fმაისი\u001Fივნისი\u001Fივლისი\u001Fაგვისტო\u001Fსექტემბერი\u001Fოქტომბერი\u001Fნოემბერი\u001Fდეკემბერი\u001Elong\u001F\u0001d\u0001 \u0001@m1\u0001, \u0001y\u0001\u001Ew0\u001Fკვირა\u001Fორშაბათი\u001Fსამშაბათი\u001Fოთხშაბათი\u001Fხუთშაბათი\u001Fპარასკევი\u001Fშაბათი\u001Efull\u001F\u0001@w0\u0001, \u0001dd\u0001 \u0001@m1\u0001, \u0001y\u0001\u001Eday\u001F\u0001d\u0001 \u0001@m0\u0001\u001EyMMM\u001F\u0001@m0\u0001. \u0001y\u0001\u001EyMMMM\u001F\u0001@m1\u0001, \u0001y\u0001\u001Ew1\u001Fკვი\u001Fორშ\u001Fსამ\u001Fოთხ\u001Fხუთ\u001Fპარ\u001Fშაბ\u001Ew2\u001Fკ\u001Fო\u001Fს\u001Fო\u001Fხ\u001Fპ\u001Fშ\u001Etime\u001F\u0001H\u0001:\u0001mm\u0001\u001Eshort~d\u001F\u0001dd\u0001.\u0001MM\u0001.\u0001yy\u0001 – \u0002dd\u0002.\u0001MM\u0001.\u0001yy\u0001\u001Eshort~M\u001F\u0001dd\u0001.\u0001MM\u0001.\u0001yy\u0001 – \u0002dd\u0002.\u0002MM\u0002.\u0001yy\u0001\u001Eshort~y\u001F\u0001dd\u0001.\u0001MM\u0001.\u0001yy\u0001 – \u0002dd\u0002.\u0002MM\u0002.\u0002yy\u0002\u001Emedium~d\u001F\u0001d\u0001–\u0002d\u0002 \u0001@m0\u0001, \u0001y\u0001\u001Emedium~M\u001F\u0001dd\u0001 \u0001@m0\u0001. – \u0002dd\u0002 \u0002@m0\u0002. \u0001y\u0001\u001Emedium~y\u001F\u0001dd\u0001 \u0001@m0\u0001. \u0001y\u0001 – \u0002d\u0002 \u0002@m0\u0002. \u0002y\u0002\u001Elong~d\u001F\u0001d\u0001–\u0002d\u0002 \u0001@m1\u0001, \u0001y\u0001\u001Elong~M\u001F\u0001dd\u0001 \u0001@m1\u0001. – \u0002dd\u0002 \u0002@m1\u0002. \u0001y\u0001\u001Elong~y\u001F\u0001dd\u0001 \u0001@m1\u0001. \u0001y\u0001 – \u0002d\u0002 \u0002@m1\u0002. \u0002y\u0002\u001Eday~d\u001F\u0001d\u0001–\u0002d\u0002 \u0001@m0\u0001\u001Eday~M\u001F\u0001d\u0001 \u0001@m0\u0001 – \u0002d\u0002 \u0002@m0\u0002\u001Eday~y\u001F\u0001dd\u0001 \u0001@m0\u0001. \u0001y\u0001 – \u0002d\u0002 \u0002@m0\u0002. \u0002y\u0002\u001Ekab\u001Dshort\u001F\u0001d\u0001/\u0001M\u0001/\u0001y\u0001\u001Em0\u001FYen\u001FFur\u001FMeɣ\u001FYeb\u001FMay\u001FYun\u001FYul\u001FƔuc\u001FCte\u001FTub\u001FNun\u001FDuǧ\u001Emedium\u001F\u0001d\u0001 \u0001@m0\u0001, \u0001y\u0001\u001Em1\u001FYennayer\u001FFuṛar\u001FMeɣres\u001FYebrir\u001FMayyu\u001FYunyu\u001FYulyu\u001FƔuct\u001FCtembeṛ\u001FTubeṛ\u001FNunembeṛ\u001FDuǧembeṛ\u001Elong\u001F\u0001d\u0001 \u0001@m1\u0001 \u0001y\u0001\u001Ew0\u001FAcer\u001FArim\u001FAram\u001FAhad\u001FAmhad\u001FSem\u001FSed\u001Efull\u001F\u0001@w0\u0001 \u0001d\u0001 \u0001@m1\u0001 \u0001y\u0001\u001Eday\u001F\u0001d\u0001 \u0001@m0\u0001\u001EE\u001F\u0001@w0\u0001\u001Ew1\u001FC\u001FR\u001FR\u001FH\u001FM\u001FS\u001FS\u001EEEEEE\u001F\u0001@w1\u0001\u001Ep0\u001Fn tufat\u001Fn tufat\u001Fn tufat\u001Fn tufat\u001Fn tufat\u001Fn tufat\u001Fn tufat\u001Fn tufat\u001Fn tufat\u001Fn tufat\u001Fn tufat\u001Fn tufat\u001Fn tmeddit\u001Fn tmeddit\u001Fn tmeddit\u001Fn tmeddit\u001Fn tmeddit\u001Fn tmeddit\u001Fn tmeddit\u001Fn tmeddit\u001Fn tmeddit\u001Fn tmeddit\u001Fn tmeddit\u001Fn tmeddit\u001Fn tufat\u001Fn tmeddit\u001Eshort~d\u001F\u0001y\u0001-\u0001MM\u0001-\u0001dd\u0001 – \u0001y\u0001-\u0001MM\u0001-\u0002dd\u0002\u001Eshort~M\u001F\u0001y\u0001-\u0001MM\u0001-\u0001dd\u0001 – \u0001y\u0001-\u0002MM\u0002-\u0002dd\u0002\u001Eshort~y\u001F\u0001y\u0001-\u0001MM\u0001-\u0001dd\u0001 – \u0002y\u0002-\u0002MM\u0002-\u0002dd\u0002\u001Emedium~d\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001–\u0002d\u0002\u001Emedium~M\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001 – \u0002@m0\u0002 \u0002d\u0002\u001Emedium~y\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001 – \u0002y\u0002 \u0002@m0\u0002 \u0002d\u0002\u001Elong~d\u001F\u0001y\u0001 \u0001@m1\u0001 \u0001d\u0001–\u0002d\u0002\u001Elong~M\u001F\u0001y\u0001 \u0001@m1\u0001 \u0001d\u0001 – \u0002@m1\u0002 \u0002d\u0002\u001Elong~y\u001F\u0001y\u0001 \u0001@m1\u0001 \u0001d\u0001 – \u0002y\u0002 \u0002@m1\u0002 \u0002d\u0002\u001Eday~d\u001F\u0001@m0\u0001 \u0001d\u0001–\u0002d\u0002\u001Eday~y\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001 – \u0002y\u0002 \u0002@m0\u0002 \u0002d\u0002\u001Ekam\u001Dshort\u001F\u0001dd\u0001/\u0001MM\u0001/\u0001y\u0001\u001Em0\u001FMbe\u001FKel\u001FKtũ\u001FKan\u001FKtn\u001FTha\u001FMoo\u001FNya\u001FKnd\u001FĨku\u001FĨkm\u001FĨkl\u001Emedium\u001F\u0001d\u0001 \u0001@m0\u0001 \u0001y\u0001\u001Em1\u001FMwai wa mbee\u001FMwai wa kelĩ\u001FMwai wa katatũ\u001FMwai wa kana\u001FMwai wa katano\u001FMwai wa thanthatũ\u001FMwai wa muonza\u001FMwai wa nyaanya\u001FMwai wa kenda\u001FMwai wa ĩkumi\u001FMwai wa ĩkumi na ĩmwe\u001FMwai wa ĩkumi na ilĩ\u001Elong\u001F\u0001d\u0001 \u0001@m1\u0001 \u0001y\u0001\u001Ew0\u001FWa kyumwa\u001FWa kwambĩlĩlya\u001FWa kelĩ\u001FWa katatũ\u001FWa kana\u001FWa katano\u001FWa thanthatũ\u001E",
    "full\u001F\u0001@w0\u0001, \u0001d\u0001 \u0001@m1\u0001 \u0001y\u0001\u001Ew1\u001FWky\u001FWkw\u001FWkl\u001FWtũ\u001FWkn\u001FWtn\u001FWth\u001Ew2\u001FY\u001FW\u001FE\u001FA\u001FA\u001FA\u001FA\u001Etime\u001F\u0001H\u0001:\u0001mm\u0001\u001Eshort~d\u001F\u0001y\u0001-\u0001MM\u0001-\u0001dd\u0001 – \u0001y\u0001-\u0001MM\u0001-\u0002dd\u0002\u001Eshort~M\u001F\u0001y\u0001-\u0001MM\u0001-\u0001dd\u0001 – \u0001y\u0001-\u0002MM\u0002-\u0002dd\u0002\u001Eshort~y\u001F\u0001y\u0001-\u0001MM\u0001-\u0001dd\u0001 – \u0002y\u0002-\u0002MM\u0002-\u0002dd\u0002\u001Emedium~d\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001–\u0002d\u0002\u001Emedium~M\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001 – \u0002@m0\u0002 \u0002d\u0002\u001Emedium~y\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001 – \u0002y\u0002 \u0002@m0\u0002 \u0002d\u0002\u001Elong~d\u001F\u0001y\u0001 \u0001@m1\u0001 \u0001d\u0001–\u0002d\u0002\u001Elong~M\u001F\u0001y\u0001 \u0001@m1\u0001 \u0001d\u0001 – \u0002@m1\u0002 \u0002d\u0002\u001Elong~y\u001F\u0001y\u0001 \u0001@m1\u0001 \u0001d\u0001 – \u0002y\u0002 \u0002@m1\u0002 \u0002d\u0002\u001Eday~d\u001F\u0001@m0\u0001 \u0001d\u0001–\u0002d\u0002\u001Eday~y\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001 – \u0002y\u0002 \u0002@m0\u0002 \u0002d\u0002\u001Ekde\u001Dshort\u001F\u0001dd\u0001/\u0001MM\u0001/\u0001y\u0001\u001Em0\u001FJan\u001FFeb\u001FMac\u001FApr\u001FMei\u001FJun\u001FJul\u001FAgo\u001FSep\u001FOkt\u001FNov\u001FDes\u001Emedium\u001F\u0001d\u0001 \u0001@m0\u0001 \u0001y\u0001\u001Em1\u001FMwedi Ntandi\u001FMwedi wa Pili\u001FMwedi wa Tatu\u001FMwedi wa Nchechi\u001FMwedi wa Nnyano\u001FMwedi wa Nnyano na Umo\u001FMwedi wa Nnyano na Mivili\u001FMwedi wa Nnyano na Mitatu\u001FMwedi wa Nnyano na Nchechi\u001FMwedi wa Nnyano na Nnyano\u001FMwedi wa Nnyano na Nnyano na U\u001FMwedi wa Nnyano na Nnyano na M\u001Elong\u001F\u0001d\u0001 \u0001@m1\u0001 \u0001y\u0001\u001Ew0\u001FLiduva lyapili\u001FLiduva lyatatu\u001FLiduva lyanchech