\u001Fب\u001Eks-Deva\u001Dshort\u001F\u0001d\u0001/\u0001M\u0001/\u0001yy\u0001\u001Em0\u001Fजनवरी\u001Fफ़रवरी\u001Fमार्च\u001Fअप्रैल\u001Fमई\u001Fजून\u001Fजुलाई\u001Fअगस्त\u001Fसतुंबर\u001Fअक्तूबर\u001Fनवूमबर\u001Fदसमबर\u001Emedium\u001F\u0001d\u0001 \u0001@m0\u0001 \u0001y\u0001\u001Em1\u001Fजनवरी\u001Fफ़रवरी\u001Fमार्च\u001Fअप्रैल\u001Fमई\u001Fजून\u001Fजुलाई\u001Fअगस्त\u001Fसतमबर\u001Fअक्तूबर\u001Fनवमबर\u001Fदसमबर\u001Elong\u001F\u0001d\u0001 \u0001@m1\u0001 \u0001y\u0001\u001Ew0\u001Fआथवार\u001Fच़ंदिरवार\u001Fबोमवार\u001Fबोदवार\u001Fब्रेसवार\u001Fजुमा\u001Fबटवार\u001Efull\u001F\u0001@w0\u0001, \u0001d\u0001 \u0001@m1\u0001 \u0001y\u0001\u001EyMMM\u001F\u0001y\u0001 \u0001@m0\u0001\u001EyMMMM\u001F\u0001y\u0001 \u0001@m1\u0001\u001Em2\u001Fजनवरी\u001Fफ़रवरी\u001Fमार्च\u001Fअप्रैल\u001Fमई\u001Fजून\u001Fजुलाई\u001Fअगस्त\u001Fसतुंबर\u001Fअकतुम्बर\u001Fनवूमबर\u001Fदसमबर\u001EMMM\u001F\u0001@m2\u0001\u001Ew1\u001Fआथवार\u001Fचंदिरवार\u001Fबुवार\u001Fबोदवार\u001Fब्रेसवार\u001Fजुम्मा\u001Fबटवार\u001EEEEE\u001F\u0001@w1\u0001\u001Ew2\u001Fअ\u001Fच\u001Fब\u001Fब\u001Fब\u001Fज\u001Fब\u001Etime\u001F\u0001@p0\u0001 \u0001h\u0001:\u0001mm\u0001\u001Eshort~d\u001F\u0001yy\u0001-\u0001MM\u0001-\u0001dd\u0001 – \u0001yy\u0001-\u0001MM\u0001-\u0002dd\u0002\u001Eshort~M\u001F\u0001yy\u0001-\u0001MM\u0001-\u0001dd\u0001 – \u0001yy\u0001-\u0002MM\u0002-\u0002dd\u0002\u001Eshort~y\u001F\u0001yy\u0001-\u0001MM\u0001-\u0001dd\u0001 – \u0002yy\u0002-\u0002MM\u0002-\u0002dd\u0002\u001Emedium~d\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001–\u0002d\u0002\u001Emedium~M\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001 – \u0002@m0\u0002 \u0002d\u0002\u001Emedium~y\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001 – \u0002y\u0002 \u0002@m0\u0002 \u0002d\u0002\u001Elong~d\u001F\u0001y\u0001 \u0001@m1\u0001 \u0001d\u0001–\u0002d\u0002\u001Elong~M\u001F\u0001y\u0001 \u0001@m1\u0001 \u0001d\u0001 – \u0002@m1\u0002 \u0002d\u0002\u001Elong~y\u001F\u0001y\u0001 \u0001@m1\u0001 \u0001d\u0001 – \u0002y\u0002 \u0002@m1\u0002 \u0002d\u0002\u001Eday~d\u001F\u0001@m0\u0001 \u0001d\u0001–\u0002d\u0002\u001Eday~y\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001 – \u0002y\u0002 \u0002@m0\u0002 \u0002d\u0002\u001Eksb\u001Dshort\u001F\u0001dd\u0001/\u0001MM\u0001/\u0001y\u0001\u001Em0\u001FJan\u001FFeb\u001FMac\u001FApr\u001FMei\u001FJun\u001FJul\u001FAgo\u001FSep\u001FOkt\u001FNov\u001FDes\u001Emedium\u001F\u0001d\u0001 \u0001@m0\u0001 \u0001y\u0001\u001Em1\u001FJanuali\u001FFebluali\u001FMachi\u001FAplili\u001FMei\u001FJuni\u001FJulai\u001FAgosti\u001FSeptemba\u001FOktoba\u001FNovemba\u001FDesemba\u001Elong\u001F\u0001d\u0001 \u0001@m1\u0001 \u0001y\u0001\u001Ew0\u001FJumaapii\u001FJumaatatu\u001FJumaane\u001FJumaatano\u001FAlhamisi\u001FIjumaa\u001FJumaamosi\u001Efull\u001F\u0001@w0\u0001, \u0001d\u0001 \u0001@m1\u0001 \u0001y\u0001\u001Ew1\u001FJpi\u001FJtt\u001FJmn\u001FJtn\u001FAlh\u001FIju\u001FJmo\u001Ew2\u001F2\u001F3\u001F4\u001F5\u001FA\u001FI\u001F1\u001Etime\u001F\u0001H\u0001:\u0001mm\u0001\u001Eshort~d\u001F\u0001y\u0001-\u0001MM\u0001-\u0001dd\u0001 – \u0001y\u0001-\u0001MM\u0001-\u0002dd\u0002\u001Eshort~M\u001F\u0001y\u0001-\u0001MM\u0001-\u0001dd\u0001 – \u0001y\u0001-\u0002MM\u0002-\u0002dd\u0002\u001Eshort~y\u001F\u0001y\u0001-\u0001MM\u0001-\u0001dd\u0001 – \u0002y\u0002-\u0002MM\u0002-\u0002dd\u0002\u001Emedium~d\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001–\u0002d\u0002\u001Emedium~M\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001 – \u0002@m0\u0002 \u0002d\u0002\u001Emedium~y\u001F\u0001y\u0001 \u0001@m0\u0001 \u0001d\u0001 – \u0002y\u0002 \u0002@m0\u0002 \u0002d\u0002\u001Elong~d\u001F\u0001y\u0001 \u0001@m1\u0001 \u0001d\u0001–\u0002d\u0002\u001Elong~M\u001F\u0001y\u0001 \u0001@m1\u0001 \u0001d\u0001 – \u0002@m1\u0002 \u0002d\u0002\u001Elong~y\u001F\u0001y\u0001 \u0001@m1\u0001 \u0001d\u0001 – \u0002y\u0002 \u0002@m1\u0002 \u0002d\u0002\u001Eday~d\u001F\u0001@m0\u0001 \u0001d\u0001–\u0002d\u0002\u001Eday~y\u001F\u0001y\u0001 \u0001@m0\u000